    /* Wording decides the button colour, so a destructive action reads as one
       without every call site having to say so. Word boundaries matter here:
       an unanchored "bin" matched "combine", and "los" must not match
       "close". */
    var DESTRUCTIVE = /\b(?:delet\w*|remov\w*|clear\w*|permanent\w*|trash\w*|discard\w*|overwrit\w*|los\w*|undone|bin)\b/i;
    var looksDestructive = DESTRUCTIVE.test(String(message));
