      appScroller().off("scroll.brandDrop").on("scroll.brandDrop", closeDropdown);
      jq_default("#pm-grid-area .wcbat-table-wrap, #grid-area .wcbat-table-wrap").on("scroll.brandDrop", closeDropdown);
