        var $dropzone = jq_default('<div id="wcbat-gui-dropzone"><div id="wcbat-gui-drop-inner"><p id="wcbat-gui-drop-text">Drop files to upload</p><p id="wcbat-gui-drop-or">or</p><button class="wcbat-btn wcbat-btn-secondary" id="wcbat-gui-select-files">Select Files</button>' + (maxSize ? '<p id="wcbat-gui-drop-max">Maximum upload file size: ' + maxSize + ".</p>" : "") + '</div><div id="wcbat-gui-upload-progress" class="wcbat-hidden"></div></div>');
        var $fileInput = jq_default('<input type="file" id="wcbat-gui-file-input" accept="image/*" multiple class="wcbat-hidden">');
        $uploadPanel.append($dropzone).append($fileInput);
