        $barScroll.append($barThumbs);
        $barLeft.append($barDone);
        $bar.append($barLeft).append($barScroll);
        var $inner = jq_default('<div id="wcbat-gallery-ui-inner"></div>');
        $inner.append($topBar).append($uploadPanel).append($main).append($bar);
        $ui.append($inner);
