            var $label = jq_default('<label class="wcbat-gui-detail-label"></label>').text(labelText);
            var $inp = isTextarea ? jq_default('<textarea class="wcbat-gui-detail-input" rows="2"></textarea>').val(val || "") : jq_default('<input type="text" class="wcbat-gui-detail-input">').val(val || "");
            $inp.attr("id", inputId);
            wcbatImageFieldSaver($inp, img.id, inputId.split("-").pop(), $inp.val());
            $wrap2.append($label).append($inp);
