      return '<th class="wcbat-col-filter-th" data-col-filter="' + key + '" style="cursor:pointer;user-select:none;white-space:nowrap;' + (style || colStyle(key)) + '"><span style="display:inline-flex;align-items:center;gap:2px;">' + label + '<span class="wcbat-col-filter-icon" style="' + colour + '">' + S.FILTER_FUNNEL_SVG + "</span></span></th>";
