      var $item = jq_default('<div class="wcbat-gui-img' + (isSelected ? " selected" : "") + '" data-id="' + img.id + '"></div>');
      $item.css("background-image", "url(" + img.url + ")");
      $item.on("click", function() {
        if ($item.hasClass("selected")) {
          $item.removeClass("selected");
          selectedId = 0;
          selectedUrl = "";
        } else {
          $grid.find(".wcbat-gui-img").removeClass("selected");
          $item.addClass("selected");
          selectedId = img.id;
          selectedUrl = img.url;
          showPipDetail(img);
        }
        sayWhatTheButtonDoes();
      });
