    function loadPipImages(page, append) {
      if (pipLoading) return;
      pipLoading = true;
      if (!append) $grid.html('<div id="wcbat-vargui-loading">Loading...</div>');
      var pinnedIds = selectedId ? [selectedId] : [];
      var postData = {
        page,
        search: pipSearch
      };
      if (pinnedIds.length) postData.exclude_ids = pinnedIds;
      function doPipLoad(skipEmpty) {
        api("GET", "/media", postData, function(data) {
          pipLoading = false;
          pipPage = page;
          pipTotal = data.total;
          pipPages = data.total_pages;
          if (!append && !skipEmpty) $grid.empty();
          $gridWrap.find("#wcbat-varpip-loadmore").remove();
          jq_default.each(data.images, function(i, img) {
            appendPipImage(img);
          });
          var loadedCount = $grid.children().length;
          $pipCount.text("Showing " + loadedCount + " of " + (pipTotal + pinnedIds.length) + " media items");
          if (pipPage < pipPages) {
            var $more = jq_default('<button id="wcbat-varpip-loadmore">Load More (' + (pipTotal + pinnedIds.length) + " total)</button>");
            $more.on("click", function() {
              loadPipImages(pipPage + 1, true);
            });
            $gridWrap.append($more);
          }
        }, function() {
          pipLoading = false;
          $grid.html('<p style="color:var(--muted);padding:20px;">Failed to load images.</p>');
        });
      }
      if (!append && pinnedIds.length) {
        api("GET", "/media/by-ids", {
          ids: pinnedIds
        }, function(pinnedImgs) {
          $grid.empty();
          jq_default.each(pinnedImgs, function(i, img) {
            appendPipImage(img);
          });
          doPipLoad(true);
        }, function() {
          doPipLoad(false);
        });
      } else {
        doPipLoad(false);
      }
    }
