    var $dropzone = jq_default('<div id="wcbat-bgui-dropzone"><div id="wcbat-bgui-drop-inner"><p id="wcbat-bgui-drop-text">Drop files to upload</p><p id="wcbat-bgui-drop-or">or</p><button class="wcbat-btn wcbat-btn-secondary" id="wcbat-bgui-select-files">Select Files</button>' + (maxSize ? '<p id="wcbat-bgui-drop-max">Maximum upload file size: ' + maxSize + ".</p>" : "") + '</div><div id="wcbat-bgui-upload-progress" class="wcbat-hidden"></div></div>');
