    var $textarea = jq_default('<textarea style="width:100%;min-height:140px;box-sizing:border-box;border:1px solid var(--wcbat-border);border-radius:var(--wcbat-radius-sm);padding:10px;font-size:13px;font-family:inherit;resize:vertical;" placeholder="' + opts.placeholder + '"></textarea>');
