        var $fSaleDateFrom = $2('<input type="date" class="wcbat-input" style="height:32px;font-size:13px;">');
        var $fSaleDateTo = $2('<input type="date" class="wcbat-input" style="height:32px;font-size:13px;">');
        $pricingGrid.append(field("Set Regular Price", $fRegPrice));
