        var $notice = $2('<div style="font-size:12px;color:var(--wcbat-text-muted);display:flex;align-items:center;gap:6px;"><span style="color:var(--caution);">&#9888;</span> Changes are applied to the grid. Click Save Changes to persist.</div>');
        $applyBtn = $2('<button class="wcbat-btn wcbat-btn-primary">Apply to ' + selectedVids.length + " Variation" + (selectedVids.length !== 1 ? "s" : "") + "</button>");
        var $cancelBtn = $2('<button class="wcbat-btn wcbat-btn-ghost">Cancel</button>');
