    /* Copy a product id.
     *
     * navigator.clipboard is the right way to do it but only exists on a
     * secure origin, and plenty of shops still run their admin over plain
     * http, so a hidden field and execCommand stands behind it. The button
     * shows a tick either way, and says so if neither worked - a copy button
     * that silently does nothing is worse than one that admits it. */
    function wcbatCopyText(text) {
      if (navigator.clipboard && window.isSecureContext) {
        return navigator.clipboard.writeText(text);
      }
      return new Promise(function(resolve, reject) {
        var el = document.createElement("textarea");
        el.value = text;
        el.setAttribute("readonly", "");
        el.style.position = "fixed";
        el.style.top = "-1000px";
        document.body.appendChild(el);
        el.select();
        var ok = false;
        try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
        document.body.removeChild(el);
        ok ? resolve() : reject(new Error("copy refused"));
      });
    }

