    $2(document).on("click", "#bulk-create-cat-btn", function() {
      if ($2("#wcbat-bulk-cat-overlay").length) return;
      var $overlay = $2('<div id="wcbat-bulk-cat-overlay" class="wcbat-overlay"></div>');
      var $modal = $2('<div style="background:var(--paper);border:1px solid var(--ink);border-radius:var(--r-xl);width:100%;max-width:860px;max-height:92vh;display:flex;flex-direction:column;overflow:hidden;"></div>');
      var $header = $2('<div class="wcbat-modal-header"></div>');
      $header.append("<h2>Bulk Create Categories</h2>");
      var $closeBtn = $2('<button class="wcbat-modal-close">&times;</button>');
      $header.append($closeBtn);
      var $body = $2('<div style="padding:20px;flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:16px;"></div>');
      var $dispCard = $2('<div class="wcbat-panel-card" style="margin-bottom:0;"></div>');
      $dispCard.append('<div class="wcbat-panel-head">Display Type</div>');
      var $dispBody = $2('<div class="wcbat-panel-body"></div>');
      var $dispSel = $2('<select class="wcbat-be-select" style="width:100%;box-sizing:border-box;"><option value="default">Default</option><option value="products">Products Only</option><option value="subcategories">Subcategories Only</option><option value="both">Both</option></select>');
      $dispBody.append($dispSel);
      $dispBody.append(catDisplayTypeNote());
      $dispCard.append($dispBody);
      $body.append($dispCard);
      var $treeCard = $2('<div class="wcbat-panel-card" style="margin-bottom:0;"></div>');
      $treeCard.append('<div class="wcbat-panel-head">Category Trees</div>');
      var $treeBody = $2('<div class="wcbat-panel-body" style="display:flex;flex-direction:column;gap:10px;"></div>');
      var $help = $2('<div style="font-size:12px;color:var(--wcbat-text-muted);line-height:1.6;"></div>');
      $help.html('<strong>Syntax:</strong><div style="margin-top:6px;display:flex;flex-direction:column;gap:4px;"><span><strong>;</strong> &mdash; separates independent trees</span><span><strong>&gt;Name</strong> &mdash; child of the top-level parent</span><span><strong>/Name</strong> &mdash; child of the preceding &gt; item</span><span><strong>//Name</strong> &mdash; each extra / goes one level deeper</span></div><div style="margin-top:8px;"><strong>Example:</strong> Accessories&gt;Adapters/USB Adapters/WiFi Adapters/&gt;Smart Watches;Electronics&gt;TVs/OLED//4K</div>');
      $treeBody.append($help);
      var $textarea = $2('<textarea style="width:100%;min-height:160px;box-sizing:border-box;border:1px solid var(--wcbat-border);border-radius:var(--wcbat-radius-sm);padding:10px;font-size:13px;font-family:monospace;resize:vertical;" placeholder=""></textarea>');
      $treeBody.append($textarea);
      var $result = $2('<div style="font-size:13px;"></div>');
      $treeBody.append($result);
      $treeCard.append($treeBody);
      $body.append($treeCard);
      var $footer = $2('<div class="wcbat-modal-footer" style="justify-content:flex-end;gap:10px;flex-shrink:0;"></div>');
      var $cancelBtn = $2('<button class="wcbat-btn wcbat-btn-ghost">Cancel</button>');
      var $createBtn = $2('<button class="wcbat-btn wcbat-btn-primary">Create Categories</button>');
      $footer.append($cancelBtn).append($createBtn);
      $modal.append($header).append($body).append($footer);
      $overlay.append($modal);
      $2("body").append($overlay);
      setTimeout(function() {
        $textarea.focus();
      }, 50);
      function close() {
        $overlay.remove();
      }
      $closeBtn.on("click", close);
      $cancelBtn.on("click", close);
      $overlay.on("click", function(e) {
        if ($2(e.target).is($overlay)) close();
      });
      /**
       * Markup is not a category name.
       *
       * The parser reads ">" as "one level down", so a stray <b></b> in a
       * pasted path was read as names: "ZZ M1>ZZ M2><b></b>/ZZ M3" really
       * created categories called "<b", "<" and "b", and filed the genuine
       * "ZZ M3" underneath the one called "<". They then showed on the shop's
       * category lists like any other category.
       */
      function withoutMarkup(raw) {
        return String(raw || "")
          .replace(/<[^<>]*>/g, "")   /* whole tags go */
          .replace(/[<]/g, "");       /* a stray "<" is not a name either */
      }
      function parseTreeString(raw) {
        var items = [];
        var i = 0;
        var len = raw.length;
        while (i < len) {
          var depth = 0;
          if (raw[i] === ">") {
            depth = 1;
            i++;
          } else if (raw[i] === "/") {
            var slashCount = 0;
            while (i < len && raw[i] === "/") {
              slashCount++;
              i++;
            }
            depth = slashCount + 1;
          } else {
            depth = 0;
          }
          var name = "";
          while (i < len && raw[i] !== ">" && raw[i] !== "/") {
            name += raw[i];
            i++;
          }
          name = name.trim();
          if (name) items.push({
            name,
            depth
          });
        }
        return items;
      }
      $createBtn.on("click", function() {
        var raw = withoutMarkup($textarea.val()).trim();
        if (!raw) {
          $result.html('<span class="wcbat-text-danger">Please enter at least one category tree.</span>');
          return;
        }
        var trees = raw.split(";").map(function(t) {
          return t.trim();
        }).filter(function(t) {
          return t !== "";
        });
        if (!trees.length) {
          $result.html('<span class="wcbat-text-danger">Please enter at least one category tree.</span>');
          return;
        }
        var allItems = [];
        trees.forEach(function(tree, treeIndex) {
          /* Which tree each name came from. Every tree between semicolons
             stands on its own; they were sent as one flat list, so the parents
             of one tree were still standing when the next began and a new tree
             was filed inside the one before it. */
          parseTreeString(tree).forEach(function(item) {
            item.tree = treeIndex;
            allItems.push(item);
          });
        });
        if (!allItems.length) {
          $result.html('<span class="wcbat-text-danger">Could not parse any categories from the input.</span>');
          return;
        }
        $createBtn.prop("disabled", true).text("Creating...");
        $result.empty();
        api("POST", "/categories/bulk", {
          items: allItems,
          display: $dispSel.val()
        }, function(data) {
          loadCatManager();
          var msg = "";
          if (data.created && data.created.length) {
            msg += '<div style="color:var(--accent);margin-bottom:6px;">\u2713 Created: ' + safeText(data.created.join(", ")) + "</div>";
          }
          if (data.skipped && data.skipped.length) {
            msg += '<div style="color:var(--danger-c);">\u26A0 Skipped (already exists): ' + safeText(data.skipped.join(", ")) + "</div>";
          }
          /* Said apart from the ones that really are already there. A name
             whose level above is missing used to be reported as "already
             exists" although it had never existed, so the owner was told to
             look for a category that was not there. */
          if (data.no_parent && data.no_parent.length) {
            msg += '<div style="color:var(--danger-c);">\u26A0 Not created, because the level above is missing from the path: ' + safeText(data.no_parent.join(", ")) + "</div>";
          }
          if (!msg) msg = '<div style="color:var(--wcbat-text-muted);">No categories were created.</div>';
          $result.html(msg);
          $textarea.val("");
          $createBtn.prop("disabled", false).text("Create Categories");
        }, function(err) {
          $result.html('<span class="wcbat-text-danger">' + safeText(err) + "</span>");
          $createBtn.prop("disabled", false).text("Create Categories");
        });
      });
    });
