    $2(document).on("click", "#cat-bulk-delete-btn", function() {
      var ids = [];
      $2("#cat-card-grid .wcbat-card-cb:checked").each(function() {
        ids.push(parseInt($2(this).data("id"), 10));
      });
      if (!ids.length) return;
      /* What this does to the products was never mentioned, so a product that
         was only in the category being deleted was left reachable by nobody -
         still on sale, but in no category page, menu or filter. */
      var defaultName = "the default category";
      jq_default.each(S.allCatData || [], function(i, c) {
        if (c.term_id === S.defaultCatId || c.id === S.defaultCatId) defaultName = c.name;
      });
      pmConfirm("Delete " + ids.length + " categor" + (ids.length !== 1 ? "ies" : "y") + "? Subcategories move up one level, and any product left without a category goes into " + defaultName + ".").then(function (ok) {
        if (!ok) return;
        /* Every answer counted, and one message at the end that tells the
           owner about both halves. Each branch used to speak for itself and
           whichever request finished last decided what was said - so ticking
           two and having one refused showed "1 category deleted." on its own,
           with the refusal and its reason never shown at all. */
        var done = 0;
        var movedToDefault = 0;
        var failures = [];
        var answered = 0;

        function settle() {
          if (++answered < ids.length) return;
          $2("#cat-detail-panel").hide();
          S.catNavStack = [];
          S.catDirty = false;
          loadCatManager();

          var said = done + " categor" + (done !== 1 ? "ies" : "y") + " deleted.";
          if (movedToDefault) {
            said += " " + movedToDefault + " product" + (movedToDefault !== 1 ? "s" : "")
                  + " had no other category, so " + (movedToDefault !== 1 ? "they were" : "it was")
                  + " put into " + defaultName + ".";
          }
          if (!failures.length) {
            showNotice("success", said, $2("#cat-bulk-delete-btn"));
            return;
          }
          said += " " + failures.length + " could not be deleted: " + failures[0];
          showNotice(done ? "warning" : "error", said, $2("#cat-bulk-delete-btn"));
        }

        $2.each(ids, function(i, id) {
          api("DELETE", "/categories/" + (id), {
            term_id: id
          }, function(data) {
            done++;
            movedToDefault += (data && data.moved_to_default) ? data.moved_to_default : 0;
            settle();
          }, function(err) {
            failures.push(err);
            settle();
          });
        });
      }.bind(this));
    });
