        var $dndBtn = $2('<button type="button" style="padding:7px 16px;font-size:12px;font-weight:600;border:2px solid #005DCA;border-left:1px solid #005DCA;cursor:pointer;font-family:inherit;background:var(--paper);color:#005DCA;border-radius:0 3px 3px 0;">Drag &amp; Drop Mode</button>');
