          var $si = $2('<input type="text" placeholder="Search fields..." style="width:calc(100% - 24px);margin:0 12px;border:1px solid var(--wcbat-border);border-radius:var(--wcbat-radius-sm);padding:4px 6px;font-size:12px;font-family:inherit;box-sizing:border-box;display:block;">');
