            var $fr = $2('<div style="display:flex;align-items:center;gap:8px;min-height:30px;"></div>');
            var $flbl = $2('<div style="flex:0 0 150px;font-size:12px;">' + safeText(fieldName) + "</div>");
            var $dz = $2('<div style="flex:1;min-height:28px;border:1px dashed var(--wcbat-border);border-radius:3px;padding:4px 8px;font-size:12px;display:flex;flex-wrap:wrap;gap:4px;align-items:center;background:var(--panel);"></div>');
            impRenderChips($dz, fieldName);
